reference_solution_py:
def maxSumSubarray(nums, k):
    n = len(nums)
    if k <= 0 or k > n:
        raise ValueError("invalid k")
    window_sum = sum(nums[:k])
    best = window_sum
    for i in range(k, n):
        window_sum += nums[i] - nums[i - k]
        if window_sum > best:
            best = window_sum
    return best

