def maxSumSubarray(nums, k):
    n = len(nums)
    if k <= 0 or k > n:
        raise ValueError("invalid k")
    best = None
    for i in range(n - k + 1):
        s = sum(nums[i:i + k])
        if best is None or s > best:
            best = s
    return best

